import json, hashlib, copy
from pathlib import Path
BASE=Path.cwd()
p=json.loads(Path('packet.json').read_text())
src={s['source_id']:s for s in p['entries']}
txt={k:v['text'] for k,v in src.items()}
units=[]; rels=[]; notes=[]

def span(sid,q,start=0):
 i=txt[sid].index(q,start);return {'start':i,'end':i+len(q),'quote':q}
def ev(sid,q,start=0):return {'source_id':sid,'span':span(sid,q,start)}
def E(sid):return ev(sid,txt[sid])
def comp(u,symbol,text,q=None,basis='explicit',role='local',note='',sid=None,start=None):
 sid=sid or u['source_id'];q=q if q is not None else text
 st=u['span']['start'] if start is None and sid==u['source_id'] and role=='local' else (start or 0)
 c={'symbol':symbol,'text':text,'basis':basis,'evidence':[ev(sid,q,st)],'inference_note':note,'occurrence_role':role}
 u['components'].append(c);return c

def unit(uid,sid,q,role='statement',grammar='regulative',speech='proposed',scope='case_specific',parse='literal',force='recommendation',itype='undetermined',standing='text_only',rationale='',target='operational',observed='operational',level='',alt='',uncertainty='',confidence='clear',quotation='none',markup='plain',presentation='',flags=None,start=0):
 st=span(sid,q,start)
 if role!='statement': grammar='not_institutional';itype='not_applicable';standing='not_applicable';target='not_applicable';force='nondeontic'
 u={'unit_id':uid,'source_id':sid,'span':st,'parent_unit_id':None,'grammar':grammar,'speech_act':speech,'scope':scope,'components':[],
 'institution':{'type':itype,'standing':standing,'dispute_present':False,'rationale':rationale,'evidence':[ev(sid,q,start)],'recognition':[],'authority_evidence':[]},
 'statement_target_level':target,'observed_action_level':observed,'level_rationale':level or ('The focal act concerns review, contribution, documentation, or use of the specific software option; no allocation of rule-making powers is supplied.' if role=='statement' else 'This is an observed contribution-discussion act, not a separately coded prescription.'),
 'complexity_flags':flags or ['none'],'alternative_interpretation':alt,'confidence':confidence,'uncertainty_reason':uncertainty,'record_role':role,'parse_mode':parse,'deontic_force':force,'level_alternatives':[],
 'presentation':{'quotation':quotation,'markup':markup,'rationale':presentation or 'Presentation follows the supplied occurrence.'},'disposition_events':[]}
 units.append(u);return u

def recognition(u,kind,target,evidence,rationale,basis='explicit'):
 u['institution']['recognition'].append({'kind':kind,'target':target,'basis':basis,'evidence':evidence,'rationale':rationale})
def disp(u,kind,target,evidence,rationale,basis='explicit'):
 u['disposition_events'].append({'kind':kind,'target':target,'basis':basis,'evidence':evidence,'rationale':rationale})
def rel(a,b,kind,evidence,rationale,basis='explicit',scope='not_applicable'):
 rels.append({'from_unit_id':a['unit_id'],'to_unit_id':b['unit_id'],'type':kind,'basis':basis,'rationale':rationale,'evidence':evidence,'logic_scope':scope})
def context(uid,sid,q=None,**kw):return unit(uid,sid,q or txt[sid],role='context',speech='asserted',**kw)

